"use client";

import { AnimatePresence, useIsPresent, usePresence } from "motion/react";
import {
  Children,
  type ComponentProps,
  createContext,
  isValidElement,
  useContext,
  useEffect,
  useInsertionEffect,
  useLayoutEffect,
  useRef,
  useState,
  useSyncExternalStore,
} from "react";
import { cn } from "../lib/cn";
import { useStateColor } from "../lib/css-motion";
import { createInlineEntrance } from "../lib/inline-entrance";
import { createInlinePresence } from "../lib/inline-presence";
import { createKbdExtent, createKbdKey, type KbdBox, kbdColourReadable, kbdScale } from "../lib/kbd-layout";
import { naturalGeometry } from "../lib/measured-geometry";
import { motionLimits } from "../lib/motion";
import {
  createPresentationScope,
  documentPresentation,
  MotionPresentation,
  usePresentationScope,
} from "../lib/motion-presence";
import { type MotionHostRef, useMotionHostRef } from "../lib/motion-ref";
import { type CadenceMotion, useCadenceMotion } from "../lib/provider";
import { nativeTextContext } from "../lib/text-layout";
import { useTextPresentation } from "../lib/use-text-presentation";

const committed = typeof window === "undefined" ? useEffect : useLayoutEffect;
const subscribe = () => () => {};
type Scope = ReturnType<typeof createPresentationScope>;
type Key = {
  host: HTMLElement;
  controller: ReturnType<typeof createKbdKey>;
  cm: CadenceMotion;
  value: unknown;
  present: boolean;
  box: KbdBox | null;
  exitBox?: KbdBox | null;
};
const Chord = createContext<{ keys: Map<object, Key>; scope: Scope; request(passive?: boolean): void } | null>(null);
const ChordPresent = createContext(true);

export interface KbdProps extends ComponentProps<"kbd"> {}

/** Key names are identities, including numeric labels; never keyboard state. */
function Kbd({ className, children, ...props }: KbdProps) {
  const { node, ref } = useMotionHostRef<HTMLElement>(props.ref);
  const cm = useCadenceMotion(node);
  const group = useContext(Chord);
  const groupPresent = useContext(ChordPresent);
  const parent = usePresentationScope();
  const [scope] = useState(() => createPresentationScope(node));
  const [present, remove] = usePresence();
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const initialHydration = useRef(hydrated),
    consumed = useRef(false);
  const controller = useRef<ReturnType<typeof createKbdKey> | null>(null);
  const record = useRef<Key | null>(null);
  const identity = useRef({});
  const single = useRef<{ value: unknown; policy: string } | null>(null);
  const lifecycle = useRef<ReturnType<typeof createInlinePresence> | null>(null);
  useParentCancellation(node, scope, parent, () =>
    lifecycle.current?.commit({ present, enter: false, cm: { ...cm, timeScale: 0 }, complete: () => remove?.() }),
  );
  const removal = useRef({ present, remove, ready: false, pending: false });
  useInsertionEffect(() => {
    Object.assign(removal.current, { present, remove, ready: false });
  });
  useEffect(() => {
    removal.current.ready = true;
    if (removal.current.pending && !present) remove?.();
    removal.current.pending = false;
  });
  const paint = useStateColor(
    ref,
    cm,
    ["background-color", "color", "border-top-color", "border-right-color", "border-bottom-color", "border-left-color"],
    { readability: "verified", readabilityGate: kbdColourReadable, readabilityScope: (node) => node.parentElement },
  );
  const exitBox =
    !present && group && record.current?.box ? (record.current.exitBox ?? controller.current?.sample()) : null;
  const plain = typeof children === "string" || typeof children === "number";
  useEffect(() => {
    if (!parent && node.current) documentPresentation(node.current.ownerDocument).presented = true;
  }, [parent, node]);
  committed(() => {
    const host = node.current;
    if (!host) return;
    if (!controller.current) controller.current = createKbdKey(node, group?.scope.transaction ?? scope.transaction);
    if (!lifecycle.current)
      lifecycle.current = createInlinePresence(host, group?.scope.transaction ?? scope.transaction);
    if (group && !present) {
      controller.current.prepare();
      if (record.current) record.current.exitBox = exitBox ?? null;
    } else if (record.current) record.current.exitBox = null;
    const baseline = parent ?? documentPresentation(host.ownerDocument);
    lifecycle.current.commit({
      present,
      cm: group && (!groupPresent || !group.scope.available() || (!present && !exitBox)) ? { ...cm, timeScale: 0 } : cm,
      enter:
        !consumed.current &&
        !initialHydration.current &&
        baseline.presented &&
        baseline.available() &&
        !baseline.node?.current?.hasAttribute("data-starting-style"),
      complete: () => {
        const delivery = removal.current;
        if (delivery.present) return;
        if (delivery.ready) delivery.remove?.();
        else delivery.pending = true;
      },
    });
    consumed.current = true;

    if (group) {
      const current = record.current ?? {
        host,
        controller: controller.current,
        cm,
        value: children,
        present,
        box: null,
      };
      Object.assign(current, { host, controller: controller.current, cm, value: children, present });
      record.current = current;
      group.keys.set(identity.current, current);
      group.request();
    } else {
      const policy = JSON.stringify([
        present,
        cm.mode,
        cm.timeScale,
        cm.scope.signature,
        className,
        Object.entries(props.style ?? {}).filter(([key]) => !/color|background|shadow|opacity/i.test(key)),
      ]);
      if (single.current && single.current.value === children && single.current.policy === policy) return;
      single.current = { value: children, policy };
      const origin = controller.current.prepare();
      const box = keyBox(host);
      controller.current.commit({
        revision: scope.transaction.revision("content", children),
        cm,
        destination: box ? { width: box.width, x: 0 } : null,
        origin,
        available:
          present &&
          !cm.reduced &&
          plain &&
          !interactiveParent(host) &&
          baseline.available() &&
          !nativeTextContext(host) &&
          !!kbdScale(host),
        moving: false,
        readable: !clipped(host),
      });
      controller.current.settlePosition();
      if (!baseline.available()) scope.transaction.cancel();
    }
  });
  committed(
    () => () => {
      group?.keys.delete(identity.current);
      group?.request();
      controller.current?.dispose();
      lifecycle.current?.dispose();
      controller.current = null;
      lifecycle.current = null;
    },
    [group],
  );
  return (
    <MotionPresentation scope={scope}>
      <kbd
        {...props}
        {...paint}
        ref={paint.ref}
        data-slot="kbd"
        data-motion={cm.mode}
        data-ending-style={present && groupPresent ? undefined : ""}
        aria-hidden={present && groupPresent ? props["aria-hidden"] : true}
        inert={!present || !groupPresent || props.inert || undefined}
        className={cn(
          "pointer-events-none inline-flex h-5 w-fit min-w-5 shrink-0 items-center justify-center gap-1 rounded-sm bg-muted px-1 font-sans text-xs font-medium whitespace-nowrap text-muted-foreground select-none",
          "[&_svg:not([class*='size-'])]:size-3",
          "[[data-slot=tooltip-content]_&]:bg-background/20 [[data-slot=tooltip-content]_&]:text-background dark:[[data-slot=tooltip-content]_&]:bg-background/10",
          className,
        )}
        style={{
          ...paint.style,
          ...(!present && group
            ? ({
                position: "absolute",
                left: exitBox?.x ?? 0,
                top: 0,
                ...(exitBox ? { width: exitBox.width } : {}),
              } as const)
            : {}),
          ...props.style,
        }}
      >
        {plain ? (
          <KeyText
            value={String(children)}
            scope={group?.scope ?? scope}
            visible={present && groupPresent && (!group || group.scope.available())}
          />
        ) : (
          children
        )}
      </kbd>
    </MotionPresentation>
  );
}

function KeyText({ value, scope, visible }: { value: string; scope: Scope; visible: boolean }) {
  const { node, ref } = useMotionHostRef<HTMLSpanElement>();
  const cm = useCadenceMotion(node);
  const identity = useRef({});
  const text = useTextPresentation(
    node,
    value,
    cm,
    identity.current,
    { characterStagger: false, visible, stripGeometry: true },
    scope.transaction,
  );
  return (
    <span ref={ref} data-slot="kbd-text" data-motion={cm.mode} className="inline-block shrink-0">
      {text}
    </span>
  );
}

export interface KbdGroupProps extends ComponentProps<"div"> {}

/** Stable caller keys retain native identity through membership revisions. */
function KbdGroup({ className, children, ...props }: KbdGroupProps) {
  const { node, ref } = useMotionHostRef<HTMLElement>(props.ref);
  const strip = useRef<HTMLSpanElement>(null);
  const cm = useCadenceMotion(node);
  const parent = usePresentationScope();
  const present = useIsPresent();
  const [scope] = useState(() => createPresentationScope(node));
  const [group] = useState(() => ({ keys: new Map<object, Key>(), scope, request: (_passive = false) => {} }));
  const hydrated = useSyncExternalStore(
    subscribe,
    () => false,
    () => true,
  );
  const initialHydration = useRef(hydrated),
    consumed = useRef(false);
  const presence = useRef<ReturnType<typeof createInlineEntrance> | null>(null);
  useParentCancellation(node, scope, parent, () =>
    presence.current?.commit({ present: false, enter: false, cm: { ...cm, timeScale: 0 } }),
  );
  const connection = useRef<{ flush(passive?: boolean): void; dispose(): void } | null>(null);
  const latest = useRef({ cm, present, children });
  useInsertionEffect(() => {
    if (present) scope.transaction.open();
    else scope.transaction.cancel();
  }, [scope, present]);
  useEffect(() => {
    if (!parent && node.current) documentPresentation(node.current.ownerDocument).presented = true;
  }, [parent, node]);
  committed(() => {
    latest.current = { cm, present, children };
    const host = node.current,
      content = strip.current;
    if (!host || !content) return;
    if (!presence.current) presence.current = createInlineEntrance(host);
    const baseline = parent ?? documentPresentation(host.ownerDocument);
    presence.current.commit({
      present,
      cm,
      enter:
        !consumed.current &&
        !initialHydration.current &&
        baseline.presented &&
        baseline.available() &&
        !baseline.node?.current?.hasAttribute("data-starting-style"),
    });
    consumed.current = true;
    if (!connection.current) {
      const geometry = createKbdExtent(node, content, scope.transaction);
      let alive = true,
        flushing = false,
        signature = "",
        policy = "";
      const richIds = new WeakMap<object, number>();
      const ids = new Map<object, number>();
      let id = 0;
      const redraw = () => {
        const keys = [...group.keys.values()].filter((key) => key.present);
        for (const key of keys) key.controller.write();
        if (!flushing && keys.every((key) => !key.controller.settling)) {
          for (const key of keys) key.controller.settlePosition();
          geometry.releaseAllocation();
        }
      };
      const flush = (passive = false) => {
        if (!alive || node.current !== host) return;
        const keys = [...group.keys.entries()]
          .filter(([, key]) => key.host.isConnected && key.present)
          .sort((a, b) => (a[1].host.compareDocumentPosition(b[1].host) & Node.DOCUMENT_POSITION_FOLLOWING ? -1 : 1));
        for (const key of ids.keys()) if (!group.keys.has(key)) ids.delete(key);
        const next = JSON.stringify(
          keys.map(([key, record]) => {
            if (!ids.has(key)) ids.set(key, id++);
            if (record.value && typeof record.value === "object" && !richIds.has(record.value))
              richIds.set(record.value, id++);
            return [
              ids.get(key),
              typeof record.value === "string" || typeof record.value === "number"
                ? record.value
                : record.value && typeof record.value === "object"
                  ? richIds.get(record.value)
                  : null,
            ];
          }),
        );
        const current = latest.current;
        const clock = JSON.stringify([
          current.cm.mode,
          current.cm.timeScale,
          current.cm.scope.signature,
          ...keys.map(([, key]) => [key.cm.mode, key.cm.timeScale, key.cm.scope.signature]),
        ]);
        if (!passive && next === signature && clock === policy) return;
        const semantic = signature !== "" && next !== signature;
        signature = next;
        policy = clock;
        const bounded = scope.transaction.preflightVisuals(
          new Set([host, content, ...[...group.keys.values()].map((key) => key.host)]),
        );
        if (!bounded) scope.transaction.cancel();
        const extentOrigin = geometry.prepare();
        const origins = new Map(keys.map(([, key]) => [key, key.controller.prepare()]));
        const scale = kbdScale(host);
        const rect = content.getBoundingClientRect();
        const style = getComputedStyle(content);
        let safe =
          bounded &&
          keys.length <= motionLimits.collectionVisuals &&
          keys.length === content.children.length - [...group.keys.values()].filter((key) => !key.present).length &&
          scale &&
          style.flexDirection === "row" &&
          style.flexWrap === "nowrap" &&
          style.direction === "ltr" &&
          keys.every(
            ([, key]) =>
              typeof key.value === "number" ||
              (typeof key.value === "string" && key.value.length <= motionLimits.changedGraphemes),
          ) &&
          !nativeTextContext(host) &&
          !host.contains(host.ownerDocument.activeElement);
        const boxes = new Map(
          keys.map(([, key]) => {
            if (!bounded) return [key, null] as const;
            const box = key.host.getBoundingClientRect();
            const natural = keyBox(key.host);
            return [key, natural && scale ? { width: natural.width, x: (box.left - rect.left) / scale.x } : null];
          }),
        );
        safe = safe && [...boxes.values()].every(Boolean);
        const revision = scope.transaction.revision("content", next, content);
        geometry.commit({
          cm: current.cm,
          revision,
          destination: naturalGeometry(host)?.width ?? null,
          allocation: naturalGeometry(content)?.width ?? null,
          origin: extentOrigin,
          available: !!safe && semantic && current.present && baseline.available() && !passive,
          clipped: clipped(host),
          delegate: !!host.closest('[data-slot="tooltip-content"]') || interactiveParent(host),
          complete: redraw,
          passive: () => group.request(true),
        });
        const ordered = keys.map(([, key]) => key);
        const overlap = ordered.some((key, index) => {
          const next = ordered[index + 1];
          const a = origins.get(key) ?? boxes.get(key),
            b = next && (origins.get(next) ?? boxes.get(next));
          const target = boxes.get(key);
          return a && b && target && a.x + Math.max(a.width, target.width) > b.x;
        });
        flushing = true;
        for (const key of ordered) {
          const box = boxes.get(key) ?? null;
          const origin = origins.get(key) ?? null;
          key.box = box;
          const before = ordered.slice(0, ordered.indexOf(key));
          key.controller.commit({
            revision,
            cm: key.cm,
            destination: box,
            origin,
            available: !!safe && semantic && current.present && baseline.available() && !passive,
            moving: !overlap,
            readable:
              !overlap &&
              !clipped(host) &&
              (ordered.indexOf(key) > 0 || firstKeyRoom(host, origin?.width ?? 0, box?.width ?? 0)),
            offset: () =>
              before.reduce((sum, sibling) => sum + sibling.controller.width - (sibling.box?.width ?? 0), 0),
            changed: redraw,
            passive: () => group.request(true),
          });
        }
        flushing = false;
        redraw();
      };
      const resize = () => flush(true);
      host.ownerDocument.defaultView?.addEventListener("resize", resize);
      host.ownerDocument.fonts?.addEventListener("loadingdone", resize);
      let queued = false,
        force = false;
      group.request = (passive = false) => {
        force ||= passive;
        if (!queued) {
          queued = true;
          queueMicrotask(() => {
            queued = false;
            const passive = force;
            force = false;
            if (alive) flush(passive);
          });
        }
      };
      connection.current = {
        flush,
        dispose() {
          alive = false;
          group.request = () => {};
          geometry.dispose();
          host.ownerDocument.defaultView?.removeEventListener("resize", resize);
          host.ownerDocument.fonts?.removeEventListener("loadingdone", resize);
        },
      };
    }
    connection.current.flush();
    if (!baseline.available()) scope.transaction.cancel();
  });
  committed(
    () => () => {
      connection.current?.dispose();
      connection.current = null;
      presence.current?.dispose();
      presence.current = null;
    },
    [],
  );
  return (
    <MotionPresentation scope={scope}>
      <Chord.Provider value={group}>
        <ChordPresent.Provider value={present}>
          <kbd
            {...props}
            ref={ref}
            aria-hidden={present ? props["aria-hidden"] : true}
            inert={!present || props.inert || undefined}
            data-slot="kbd-group"
            data-motion={cm.mode}
            data-ending-style={present ? undefined : ""}
            className={cn("inline-flex items-center gap-1", className)}
          >
            <span
              ref={strip}
              data-slot="kbd-strip"
              data-motion={cm.mode}
              className="relative inline-flex shrink-0 items-center gap-[inherit] [flex-flow:inherit] [justify-content:inherit]"
            >
              {Children.toArray(children).every(isValidElement) ? (
                <AnimatePresence initial={false}>{Children.toArray(children)}</AnimatePresence>
              ) : (
                children
              )}
            </span>
          </kbd>
        </ChordPresent.Provider>
      </Chord.Provider>
    </MotionPresentation>
  );
}

function clipped(host: HTMLElement) {
  for (let node: HTMLElement | null = host; node; node = node.parentElement) {
    const css = getComputedStyle(node);
    if (/(hidden|clip|scroll|auto)/.test(css.overflowX) || css.contain.includes("paint")) return true;
  }
  return false;
}

export { Kbd, KbdGroup };

/** A local cancellation envelope consumes parent close without sharing its revisions. */
function useParentCancellation(
  node: MotionHostRef<HTMLElement>,
  scope: Scope,
  parent: Scope | null,
  cancel: () => void,
) {
  const latest = useRef(cancel);
  committed(() => {
    latest.current = cancel;
  });
  committed(() => {
    const host = node.current;
    if (!parent || !host) return;
    const owner = parent.transaction.register(host);
    const join = () =>
      owner.begin(parent.transaction.revision("presence", host, host), [], {}, () => {
        scope.transaction.cancel();
        latest.current();
      });
    join();
    const off = parent.transaction.subscribeOpen(join);
    return () => {
      off();
      owner.dispose();
    };
  }, [node, scope, parent]);
}

/** Only the immediate native neighbour can constrain a growing first key. */
function firstKeyRoom(host: HTMLElement, previous: number, target: number) {
  if (target <= previous) return true;
  const sibling = host.previousSibling;
  if (!sibling) return true;
  let bounds: DOMRect;
  if (sibling.nodeType === Node.TEXT_NODE) {
    const text = sibling.textContent ?? "";
    if (text.length > motionLimits.changedGraphemes) return false;
    const length = text.trimEnd().length;
    if (!length) return true;
    const range = host.ownerDocument.createRange();
    range.setStart(sibling, 0);
    range.setEnd(sibling, length);
    bounds = range.getBoundingClientRect();
  } else if (sibling instanceof HTMLElement) bounds = sibling.getBoundingClientRect();
  else return false;
  const scale = kbdScale(host);
  const box = host.getBoundingClientRect();
  if (bounds.bottom <= box.top || bounds.top >= box.bottom) return true;
  return !!scale && (box.left - bounds.right) / scale.x >= (target - previous) / 2;
}

/** Reject caller-owned size/transform engines rather than replace their property. */
function keyBox(node: HTMLElement) {
  const css = getComputedStyle(node);
  if (
    css.transform !== "none" ||
    css.translate !== "none" ||
    css.rotate !== "none" ||
    css.scale !== "none" ||
    css.writingMode !== "horizontal-tb" ||
    !["static", "relative"].includes(css.position) ||
    css.whiteSpace !== "nowrap"
  )
    return null;
  const properties = css.transitionProperty.split(",").map((value) => value.trim()),
    times = css.transitionDuration.split(",").map(Number.parseFloat);
  if (
    properties.some(
      (property, index) =>
        ["all", "width", "height", "transform", "translate", "scale", "rotate"].includes(property) &&
        (times[index % times.length] ?? 0) > 0,
    )
  )
    return null;
  if (
    node
      .getAnimations?.()
      .some((animation) =>
        (animation.effect as KeyframeEffect | null)
          ?.getKeyframes()
          .some((frame) =>
            ["width", "height", "transform", "translate", "scale", "rotate"].some((key) => key in frame),
          ),
      )
  )
    return null;
  return naturalGeometry(node);
}

function interactiveParent(host: HTMLElement) {
  return !!host.parentElement?.closest(
    "button,a,summary,input,textarea,select,[contenteditable],[role=button],[role=menuitem],[role=option],[tabindex]",
  );
}

"use client";

import { animateSingleValue, motionValue } from "motion/react";
import { bindMotionParameters, geometryCompact, layoutCompact, motionLimits } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import type { MotionHostRef } from "./motion-ref";
import {
  createMotionTransaction,
  type MotionLease,
  type MotionRevision,
  registerTextGeometry,
} from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type KbdBox = { width: number; x: number };
type Sample = KbdBox & { widthVelocity: number; xVelocity: number };

/** The chord reserves final strip allocation; it never observes spring frames as targets. */
export function createKbdExtent(
  host: MotionHostRef<HTMLElement>,
  content: HTMLElement,
  transaction = createMotionTransaction(),
) {
  const node = host.current;
  if (!node) throw new Error("Kbd extent requires a committed group");
  const owner = transaction.register(node),
    allocation = transaction.register(content);
  const width = motionValue(0);
  let baseline: number | null = null,
    effect: Animation | null = null,
    strip: Animation | null = null;
  let lease: MotionLease | null = null,
    stripLease: MotionLease | null = null;
  let alive = true,
    restricted = false,
    bounds = [0, 0];
  let height = 0,
    passive = () => {};
  const value = () => Math.min(bounds[1] ?? 0, Math.max(bounds[0] ?? 0, width.get()));
  const stop = () => {
    width.stop();
    effect?.cancel();
    strip?.cancel();
    effect = strip = null;
    const a = lease,
      b = stripLease;
    lease = stripLease = null;
    a?.cancel();
    b?.cancel();
  };
  const off = width.on("change", () => {
    if (alive && node === host.current && lease?.current())
      (effect?.effect as KeyframeEffect | null)?.setKeyframes({ width: `${value()}px` });
  });
  const observer = new ResizeObserver((entries) => {
    const box = entries.find((entry) => entry.target === node)?.borderBoxSize?.[0];
    if (baseline === null || !box) return;
    if (Math.abs(box.inlineSize - (effect ? value() : baseline)) > 1 || Math.abs(box.blockSize - height) > 1) {
      stop();
      baseline = null;
      passive();
    }
  });
  observer.observe(node, { box: "border-box" });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    restricted = environment.hidden || environment.reduced || environment.immediate;
    if (restricted) {
      stop();
      baseline = null;
    }
  });
  return {
    prepare() {
      const sample =
        baseline === null ? null : { width: effect ? value() : baseline, velocity: effect ? width.getVelocity() : 0 };
      stop();
      return sample;
    },
    commit(input: {
      cm: CadenceMotion;
      revision: MotionRevision;
      destination: number | null;
      allocation: number | null;
      origin: { width: number; velocity: number } | null;
      available: boolean;
      clipped: boolean;
      delegate?: boolean;
      complete?: () => void;
      passive?: () => void;
    }) {
      const geometry = input.cm.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
      if (geometry.kind !== "geometry") return;
      stop();
      baseline = input.destination;
      height = node.offsetHeight;
      passive = input.passive ?? (() => {});
      const target = input.destination,
        start = input.origin;
      if (
        !alive ||
        node !== host.current ||
        !node.isConnected ||
        target === null ||
        input.allocation === null ||
        !Number.isFinite(input.allocation) ||
        input.allocation <= 0 ||
        !start ||
        !input.available ||
        restricted ||
        input.cm.reduced ||
        geometry.transition.duration === 0 ||
        !input.revision.current() ||
        !node.animate ||
        !content.animate ||
        ![start.width, target].every(Number.isFinite) ||
        Math.min(start.width, target) <= 0 ||
        (input.clipped && target > start.width)
      )
        return;
      const visuals = new Set([node, content]);
      stripLease = allocation.begin(input.revision, ["width"], { collectionVisuals: visuals }, stop);
      if (!stripLease) {
        stop();
        return;
      }
      strip = content.animate({ width: `${input.allocation}px` }, { duration: 0, fill: "both" });
      registerTextGeometry(strip, stripLease, input.cm.mode);
      if (input.delegate || target === start.width) return;
      lease = owner.begin(input.revision, ["width"], { collectionVisuals: visuals }, stop);
      if (!lease) {
        stop();
        return;
      }
      bounds = [Math.min(start.width, target), Math.max(start.width, target)];
      width.jump(start.width);
      effect = node.animate({ width: `${start.width}px` }, { duration: 0, fill: "both" });
      registerTextGeometry(effect, lease, input.cm.mode);
      const active = lease;
      animateSingleValue(width, target, {
        ...geometry.transition,
        velocity: start.velocity,
        onComplete: () => {
          if (active.current()) {
            effect?.cancel();
            effect = null;
            lease?.finish();
            lease = null;
            input.complete?.();
          }
        },
      });
    },
    releaseAllocation() {
      if (effect) return;
      strip?.cancel();
      strip = null;
      const held = stripLease;
      stripLease = null;
      held?.finish();
    },
    dispose() {
      alive = false;
      stop();
      owner.dispose();
      allocation.dispose();
      off();
      unsubscribe();
      observer.disconnect();
    },
  };
}

/** A key's border box and sibling projection have disjoint property leases.
 * The chord supplies final boxes once; scalar callbacks never measure layout. */
export function createKbdKey(host: MotionHostRef<HTMLElement>, transaction = createMotionTransaction()) {
  const node = host.current;
  if (!node) throw new Error("Kbd requires a committed key");
  const identity = host.identity;
  const owner = transaction.register(node);
  const positionOwner = transaction.register(node);
  const width = motionValue(0),
    x = motionValue(0);
  let baseline: KbdBox | null = null;
  let sizeEffect: Animation | null = null,
    positionEffect: Animation | null = null;
  let sizeLease: MotionLease | null = null,
    positionLease: MotionLease | null = null;
  let bounds = [0, 0];
  let alive = true,
    restricted = false;
  let previous: MotionRevision | null = null,
    signature = "";
  let offset = () => 0;
  let changed = () => {};
  let passive = () => {};
  let height = 0;
  let label: HTMLElement | null = null,
    labelWidth = 0,
    labelHeight = 0;
  const current = () => alive && node.isConnected && host.current === node && host.identity === identity;
  const renderedWidth = () => Math.min(bounds[1] ?? 0, Math.max(bounds[0] ?? 0, width.get()));
  const stop = () => {
    width.stop();
    x.stop();
    sizeEffect?.cancel();
    positionEffect?.cancel();
    sizeEffect = positionEffect = null;
    const a = sizeLease,
      b = positionLease;
    sizeLease = positionLease = null;
    a?.cancel();
    b?.cancel();
  };
  const write = () => {
    if (!current()) return;
    if (sizeLease?.current())
      (sizeEffect?.effect as KeyframeEffect | null)?.setKeyframes({ width: `${renderedWidth()}px` });
    if (positionLease?.current())
      (positionEffect?.effect as KeyframeEffect | null)?.setKeyframes({
        transform: `translate(${x.get() - offset()}px,0px)`,
      });
  };
  const offWidth = width.on("change", () => {
    write();
    changed();
  });
  const offX = x.on("change", write);
  const settleNative = () => {
    stop();
    baseline = null;
    changed();
    passive();
  };
  const observer = new ResizeObserver((entries) => {
    const ink = entries.find((entry) => entry.target === label)?.borderBoxSize?.[0];
    if (ink && (Math.abs(ink.inlineSize - labelWidth) > 1 || Math.abs(ink.blockSize - labelHeight) > 1)) {
      settleNative();
      return;
    }
    const box = entries.find((entry) => entry.target === node)?.borderBoxSize?.[0];
    if (!box || !baseline) return;
    const expected = sizeEffect ? renderedWidth() : baseline.width;
    if (Math.abs(box.inlineSize - expected) > 1 || Math.abs(box.blockSize - height) > 1) settleNative();
  });
  observer.observe(node, { box: "border-box" });
  node.ownerDocument.defaultView?.addEventListener("resize", settleNative);
  node.ownerDocument.fonts?.addEventListener("loadingdone", settleNative);
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    restricted = environment.hidden || environment.reduced || environment.immediate;
    if (restricted) {
      stop();
      baseline = null;
      changed();
    }
  });
  const sample = (): Sample | null =>
    baseline
      ? {
          width: sizeEffect ? renderedWidth() : baseline.width,
          x: baseline.x + (positionEffect ? x.get() : 0),
          widthVelocity: sizeEffect ? width.getVelocity() : 0,
          xVelocity: positionEffect ? x.getVelocity() : 0,
        }
      : null;
  return {
    get width() {
      return sizeEffect ? renderedWidth() : (baseline?.width ?? 0);
    },
    get running() {
      return !!(sizeEffect || positionEffect);
    },
    get settling() {
      return !!sizeEffect || x.isAnimating();
    },
    sample,
    prepare(): Sample | null {
      const current = sample();
      stop();
      if (current) baseline = current;
      return current;
    },
    write,
    commit(input: {
      revision: MotionRevision;
      cm: CadenceMotion;
      destination: KbdBox | null;
      origin: Sample | null;
      available: boolean;
      moving: boolean;
      readable: boolean;
      offset?: () => number;
      changed?: () => void;
      passive?: () => void;
    }) {
      const geometry = input.cm.parameters(bindMotionParameters(geometryCompact, "geometry.resize/measured"));
      const layout = input.cm.parameters(bindMotionParameters(layoutCompact, "layout.move/position"));
      if (geometry.kind !== "geometry" || layout.kind !== "layout") return;
      const clock = JSON.stringify([
        geometry.transition,
        layout.transition,
        input.cm.mode,
        input.available,
        input.destination,
        input.readable,
        input.moving,
      ]);
      if (previous === input.revision && signature === clock) return;
      previous = input.revision;
      signature = clock;
      stop();
      baseline = input.destination;
      offset = input.offset ?? (() => 0);
      changed = input.changed ?? (() => {});
      passive = input.passive ?? (() => {});
      const target = input.destination,
        start = input.origin;
      if (!target || !current()) return;
      height = node.offsetHeight;
      const child = node.firstElementChild;
      const next = child instanceof HTMLElement && child.getAttribute("data-slot") === "kbd-text" ? child : null;
      if (next !== label) {
        if (label) observer.unobserve(label);
        label = next;
        if (label) observer.observe(label, { box: "border-box" });
      }
      labelWidth = label?.offsetWidth ?? 0;
      labelHeight = label?.offsetHeight ?? 0;

      width.jump(target.width);
      x.jump(0);
      if (
        !start ||
        !input.available ||
        restricted ||
        input.cm.reduced ||
        geometry.transition.duration === 0 ||
        !input.revision.current() ||
        !node.animate
      )
        return;
      const valid =
        [start.width, start.x, target.width, target.x].every(Number.isFinite) &&
        Math.min(start.width, target.width) > 0;
      if (!valid) return;
      const visuals = new Set([node]);
      if (!transaction.preflightVisuals(visuals)) return;
      if (input.readable && start.width !== target.width) {
        sizeLease = owner.begin(input.revision, ["width"], { collectionVisuals: visuals }, stop);
        if (sizeLease) {
          bounds = [Math.min(start.width, target.width), Math.max(start.width, target.width)];
          width.jump(start.width);
          sizeEffect = node.animate({ width: `${start.width}px` }, { duration: 0, fill: "both" });
          registerTextGeometry(sizeEffect, sizeLease, input.cm.mode);
          const lease = sizeLease;
          animateSingleValue(width, target.width, {
            ...geometry.transition,
            velocity: start.widthVelocity,
            onComplete: () => {
              if (!lease.current()) return;
              sizeEffect?.cancel();
              sizeEffect = null;
              lease.finish();
              sizeLease = null;
              changed();
            },
          });
        }
      }
      if (input.moving && layout.transition.duration !== 0) {
        positionLease = positionOwner.begin(input.revision, ["transform"], { collectionVisuals: visuals }, stop);
        if (positionLease) {
          x.jump(start.x - target.x);
          positionEffect = node.animate(
            { transform: `translate(${x.get() - offset()}px,0px)` },
            { duration: 0, fill: "both" },
          );
          registerTextGeometry(positionEffect, positionLease, input.cm.mode);
          const lease = positionLease;
          animateSingleValue(x, 0, {
            ...layout.transition,
            velocity: start.xVelocity,
            onComplete: () => {
              // Keep compensation until all key widths have reached their destinations.
              if (!lease.current()) return;
              x.jump(0);
              write();
              changed();
            },
          });
        }
      }
      write();
    },
    settlePosition() {
      positionEffect?.cancel();
      positionEffect = null;
      const lease = positionLease;
      positionLease = null;
      lease?.finish();
    },
    dispose() {
      alive = false;
      stop();
      owner.dispose();
      positionOwner.dispose();
      offWidth();
      offX();
      unsubscribe();
      observer.disconnect();
      node.ownerDocument.defaultView?.removeEventListener("resize", settleNative);
      node.ownerDocument.fonts?.removeEventListener("loadingdone", settleNative);
    },
  };
}

/** Positive axis-aligned native coordinates, including translated popup ancestors. */
export function kbdScale(element: HTMLElement) {
  let x = 1,
    y = 1,
    current: HTMLElement | null = element;
  for (let depth = 0; current && depth < 32; depth++, current = current.parentElement) {
    const css = getComputedStyle(current);
    if (!css.transform || (css.transform !== "none" && typeof DOMMatrixReadOnly === "undefined")) return null;
    const matrix = css.transform === "none" ? null : new DOMMatrixReadOnly(css.transform);
    if (
      css.rotate !== "none" ||
      css.perspective !== "none" ||
      css.offsetPath !== "none" ||
      (matrix && (!matrix.is2D || matrix.b !== 0 || matrix.c !== 0 || matrix.a <= 0 || matrix.d <= 0))
    )
      return null;
    const scale = css.scale === "none" ? [1, 1] : css.scale.split(/\s+/).map(Number);
    const zoom = css.zoom === "normal" ? 1 : Number(css.zoom);
    const sx = (scale[0] ?? 1) * (matrix?.a ?? 1) * zoom,
      sy = (scale[1] ?? scale[0] ?? 1) * (matrix?.d ?? 1) * zoom;
    if (!Number.isFinite(sx) || !Number.isFinite(sy) || sx <= 0 || sy <= 0) return null;
    x *= sx;
    y *= sy;
  }
  return current || !Number.isFinite(x) || !Number.isFinite(y) ? null : { x, y };
}

type Neutral = { value: number; alpha: number };
type Interval = [number, number];
const contexts = new WeakMap<Document, CanvasRenderingContext2D>();

/** A single named key palette, including its actual neutral ancestor backdrop. */
export function kbdColourReadable(node: Element) {
  const background = node.parentElement && backdrop(node.parentElement);
  const surface = composite(colours(node, "background-color"), background);
  const ink = composite(colours(node, "color"), surface);
  if (!surface || !ink || (ink[0] <= surface[1] && ink[1] >= surface[0])) return false;
  const luminance = (v: number) => (v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4);
  const low = luminance(ink[1] < surface[0] ? ink[1] : surface[1]);
  const high = luminance(ink[1] < surface[0] ? surface[0] : ink[0]);
  return (high + 0.05) / (low + 0.05) >= 4.5;
}
function colours(node: Element, property: "background-color" | "color"): Neutral[] | null {
  const view = node.ownerDocument.defaultView;
  if (!view || typeof view.CanvasRenderingContext2D === "undefined") return null;
  if (property === "background-color" && view.getComputedStyle(node).backgroundImage !== "none") return null;
  let context = contexts.get(node.ownerDocument);
  if (!context) {
    const canvas = node.ownerDocument.createElement("canvas");
    canvas.width = canvas.height = 1;
    context = canvas.getContext("2d", { willReadFrequently: true }) ?? undefined;
    if (!context) return null;
    contexts.set(node.ownerDocument, context);
  }
  const values = [view.getComputedStyle(node).getPropertyValue(property)];
  const key = property === "color" ? "color" : "backgroundColor";
  for (const animation of node.getAnimations()) {
    if (!("transitionProperty" in animation) || animation.transitionProperty !== property) continue;
    for (const frame of (animation.effect as KeyframeEffect | null)?.getKeyframes() ?? [])
      if (typeof frame[key] === "string") values.push(frame[key]);
  }
  const result: Neutral[] = [];
  for (const value of new Set(values)) {
    if (!view.CSS.supports("color", value)) return null;
    context.clearRect(0, 0, 1, 1);
    context.fillStyle = value;
    context.fillRect(0, 0, 1, 1);
    const [r = 0, g = 0, b = 0, a = 0] = context.getImageData(0, 0, 1, 1).data;
    if (a && Math.max(r, g, b) !== Math.min(r, g, b)) return null;
    result.push({ value: (r + g + b) / (3 * 255), alpha: a / 255 });
  }
  return result;
}
function composite(colours: Neutral[] | null, background: Interval | null): Interval | null {
  if (!colours?.length || (!background && colours.some((colour) => colour.alpha !== 1))) return null;
  const values = colours.flatMap(({ value, alpha }) =>
    (background ?? [0, 0]).map((base) => value * alpha + base * (1 - alpha)),
  );
  return [Math.min(...values), Math.max(...values)];
}
function backdrop(node: Element) {
  const ancestry: Element[] = [];
  for (let current: Element | null = node; current; current = current.parentElement) {
    if (ancestry.length >= motionLimits.collectionVisuals) return null;
    ancestry.push(current);
  }
  let interval: Interval | null = null;
  for (const current of ancestry.reverse()) {
    const values = colours(current, "background-color");
    if (!values) return null;
    if (!interval && values.every((value) => value.alpha === 0)) continue;
    interval = composite(values, interval);
    if (!interval) return null;
  }
  return interval;
}

"use client";

import { bindMotionParameters, motionMilliseconds, presenceInline } from "./motion";
import { subscribeMotionEnvironment } from "./motion-environment";
import { createMotionTransaction, type MotionLease } from "./motion-transaction";
import type { CadenceMotion } from "./provider";

export type InlinePresenceCommit = {
  present: boolean;
  enter: boolean;
  cm: CadenceMotion;
};

/** Entrance opacity only, on the original group host. Never writes a resting opacity. */
export function createInlineEntrance(node: HTMLElement) {
  const transaction = createMotionTransaction();
  const owner = transaction.register(node);
  let current: InlinePresenceCommit | null = null;
  let lease: MotionLease | null = null;
  let animation: Animation | null = null;
  let alive = true;
  let blocked = false;
  let generation = 0;
  let signature = "";
  const cancel = () => {
    generation++;
    animation?.cancel();
    animation = null;
    lease?.cancel();
    lease = null;
  };
  const settle = () => {
    cancel();
  };
  const callerOpacity = (css = node.ownerDocument.defaultView?.getComputedStyle(node)) => {
    if (!css) return false;
    const family = css.transitionProperty.split(",").map((property) => property.trim());
    const times = css.transitionDuration.split(",").map((time) => Number.parseFloat(time));
    return (
      family.some(
        (property, index) => ["all", "opacity"].includes(property) && (times[index % times.length] ?? 0) > 0,
      ) ||
      (node.getAnimations?.() ?? []).some(
        (handle) =>
          handle !== animation &&
          (handle.effect as KeyframeEffect | null)?.getKeyframes().some((frame) => "opacity" in frame),
      )
    );
  };
  const play = (from?: string, forceImmediate = false) => {
    const input = current;
    if (!alive || !input) return;
    if (!input.present) {
      settle();
      return;
    }
    const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
    if (parameters.kind !== "visual") return;
    const clock = parameters.opacity;
    const immediate = forceImmediate || blocked || clock.duration === 0;
    if (
      (immediate && input.present) ||
      !node.isConnected ||
      typeof node.animate !== "function" ||
      (input.present && node.contains(node.ownerDocument.activeElement))
    ) {
      settle();
      return;
    }
    const css = node.ownerDocument.defaultView?.getComputedStyle(node);
    if (!css || css.display === "none" || css.visibility === "hidden") {
      settle();
      return;
    }
    if (callerOpacity(css)) {
      settle();
      return;
    }
    const epoch = ++generation;
    const revision = transaction.revision("presence", input.present, node);
    let handle: Animation | null = null;
    lease = owner.begin(revision, ["opacity"], {}, () => handle?.cancel());
    if (!lease?.current()) return;
    const owned = lease;
    handle = node.animate([{ opacity: from ?? 0 }, { opacity: css.opacity }], {
      duration: motionMilliseconds(immediate ? 0 : Number(clock.duration)),
      delay: motionMilliseconds(immediate ? 0 : Number(clock.delay ?? 0)),
      easing: `cubic-bezier(${input.cm.scope.tokens.ease.out.join(",")})`,
      fill: "both",
    });
    animation = handle;
    void handle.finished.then(
      () => {
        if (
          !alive ||
          !node.isConnected ||
          epoch !== generation ||
          !owned.current() ||
          current?.present !== input.present
        )
          return;
        settle();
      },
      () => {},
    );
    if (immediate) handle.finish();
  };
  const interact = () => {
    if (current?.present) settle();
  };
  for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
    node.addEventListener(event, interact, true);
  const opacityStyle = () => {
    const style = node.style;
    return JSON.stringify([
      style.opacity,
      style.animation,
      /(?:^|,)\s*(?:all|opacity)\s*(?:,|$)/.test(style.transitionProperty) ? style.transition : "",
      Array.from(style)
        .filter((name) => name.startsWith("--") && !/^--(?:cadence-|motion-|ease-cadence)/.test(name))
        .map((name) => [name, style.getPropertyValue(name)]),
    ]);
  };
  let callerStyle = opacityStyle();
  const observer = new MutationObserver((records) => {
    const next = opacityStyle();
    // Scoped colour clocks and inherited Cadence tokens are another owned
    // family. Only potentially conflicting caller paint revokes this channel.
    if (
      (next !== callerStyle || records.some((record) => record.attributeName !== "style")) &&
      (current?.present || callerOpacity())
    )
      settle();
    callerStyle = next;
  });
  observer.observe(node, { attributes: true, attributeFilter: ["class", "style", "disabled", "aria-disabled"] });
  const unsubscribe = subscribeMotionEnvironment(node.ownerDocument, (environment) => {
    blocked = environment.hidden || environment.immediate;
    if (blocked || (environment.reduced && animation && current?.cm.mode === "full")) {
      settle();
    }
  });
  return {
    commit(input: InlinePresenceCommit) {
      const previous = current;
      current = input;
      // Resolve the exact entrance clock on every committed policy, including native baselines.
      const parameters = input.cm.parameters(bindMotionParameters(presenceInline, "data.transition/opacity"));
      const clock = JSON.stringify(parameters);
      const retime = signature !== clock;
      signature = clock;
      const change = previous ? previous.present !== input.present : input.enter || !input.present;
      if (change) {
        const from = animation ? node.ownerDocument.defaultView?.getComputedStyle(node).opacity : undefined;
        cancel();
        play(from);
      } else if (input.cm.disabled || input.cm.timeScale === 0) {
        settle();
      } else if (retime && animation) {
        const from = node.ownerDocument.defaultView?.getComputedStyle(node).opacity;
        cancel();
        play(from);
      }
    },
    dispose() {
      alive = false;
      cancel();
      owner.dispose();
      observer.disconnect();
      unsubscribe();
      for (const event of ["focusin", "pointerdown", "keydown", "click", "beforematch"])
        node.removeEventListener(event, interact, true);
    },
  };
}

